"use client";

import { useMemo, useState } from "react";

import type { ChatMessage, IncidentChatResponse } from "@/lib/types";

type ChatPanelProps = {
  title: string;
  description: string;
  endpoint: string;
  extraBody?: Record<string, unknown>;
  suggestedPrompts?: string[];
};

export function ChatPanel({
  title,
  description,
  endpoint,
  extraBody,
  suggestedPrompts = [],
}: ChatPanelProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canSubmit = useMemo(
    () => input.trim().length > 0 && !isSubmitting,
    [input, isSubmitting],
  );

  async function submitMessage(content: string) {
    const normalized = content.trim();
    if (!normalized || isSubmitting) {
      return;
    }

    const nextMessages: ChatMessage[] = [
      ...messages,
      { role: "user", content: normalized },
    ];

    setMessages(nextMessages);
    setInput("");
    setError(null);
    setIsSubmitting(true);

    try {
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          messages: nextMessages,
          ...extraBody,
        }),
      });

      const payload = (await response.json()) as
        | IncidentChatResponse
        | { error?: { message?: string } };

      if (!response.ok || !("answer" in payload)) {
        throw new Error(
          payload && "error" in payload && payload.error?.message
            ? payload.error.message
            : "Chat request failed.",
        );
      }

      setMessages([
        ...nextMessages,
        { role: "assistant", content: payload.answer },
      ]);
    } catch (caughtError) {
      setError(
        caughtError instanceof Error
          ? caughtError.message
          : "Unexpected chat error.",
      );
      setMessages(messages);
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <section className="vault-panel flex h-full flex-col rounded-[28px]">
      <div className="border-b border-[rgba(126,163,207,0.2)] px-6 py-5">
        <p className="vault-section-title text-[11px] font-semibold uppercase">
          Conversational incident analysis
        </p>
        <h2 className="mt-2 text-xl font-semibold text-[#1a3a61]">{title}</h2>
        <p className="mt-1.5 text-sm leading-6 text-[#4d6684]">{description}</p>
        <div className="vault-accent-rule mt-4 w-36" />
      </div>

      <div className="flex-1 space-y-4 overflow-y-auto px-6 py-5">
        {suggestedPrompts.length > 0 && messages.length === 0 ? (
          <div className="space-y-3">
            <p className="text-xs font-semibold uppercase tracking-wide text-[#5d7392]">
              Suggested prompts
            </p>
            <div className="flex flex-wrap gap-2">
              {suggestedPrompts.map((prompt) => (
                <button
                  key={prompt}
                  type="button"
                  onClick={() => void submitMessage(prompt)}
                  className="vault-chat-prompt rounded-full border border-[rgba(126,163,207,0.24)] px-3.5 py-1.5 text-sm text-[#33557f] transition hover:border-[rgba(86,121,168,0.36)] hover:bg-[linear-gradient(180deg,rgba(255,255,255,0.98),rgba(239,221,111,0.28))]"
                >
                  {prompt}
                </button>
              ))}
            </div>
          </div>
        ) : null}

        {messages.length === 0 ? (
          <div className="vault-empty rounded-2xl px-4 py-6 text-sm leading-6 text-[#536b89]">
            Ask the incident assistant for summaries, likely causes, impacted
            services, or next debugging steps.
          </div>
        ) : null}

        {messages.map((message, index) => (
          <div
            key={`${message.role}-${index}-${message.content.slice(0, 12)}`}
            className={`max-w-[92%] rounded-3xl px-4 py-3 text-sm leading-6 shadow-sm ${
              message.role === "user"
                ? "vault-chat-message-user ml-auto"
                : "vault-chat-message-assistant"
            }`}
          >
            <p className="mb-1 text-[11px] font-semibold uppercase tracking-wide opacity-70">
              {message.role === "user" ? "You" : "Incident agent"}
            </p>
            <p className="whitespace-pre-wrap">{message.content}</p>
          </div>
        ))}
      </div>

      <div className="border-t border-[rgba(126,163,207,0.2)] px-6 py-5">
        {error ? (
          <p className="mb-3 rounded-xl border border-[rgba(255,194,0,0.4)] bg-[rgba(255,194,0,0.12)] px-3 py-2 text-sm text-[#7b5300]">
            {error}
          </p>
        ) : null}

        <form
          className="space-y-3"
          onSubmit={(event) => {
            event.preventDefault();
            void submitMessage(input);
          }}
        >
          <textarea
            value={input}
            onChange={(event) => setInput(event.target.value)}
            placeholder="Ask about this incident or the current incident set..."
            className="vault-input min-h-28 w-full rounded-2xl px-4 py-3 text-sm text-[#163354] transition"
          />
          <div className="flex items-center justify-between gap-3">
            <p className="text-xs leading-5 text-[#5a7090]">
              Chat stays grounded in incident data already stored by the
              platform.
            </p>
            <button
              type="submit"
              disabled={!canSubmit}
              className="vault-button-primary rounded-2xl px-4 py-2 text-sm font-semibold text-white transition disabled:cursor-not-allowed disabled:bg-slate-300 disabled:shadow-none"
            >
              {isSubmitting ? "Thinking..." : "Send"}
            </button>
          </div>
        </form>
      </div>
    </section>
  );
}
